<?php
declare(strict_types=1);

/** Cinco cursos completos, idempotentes y vinculados al catálogo botánico. */
final class ExpandedLearningCoursesSeeder
{
    public static function run(PDO $db): int
    {
        foreach (self::courses() as $course) self::store($db, $course);
        return count(self::courses());
    }
    private static function store(PDO $db, array $course): void
    {
        $category=$db->prepare('SELECT id FROM course_categories WHERE code=?'); $category->execute([$course['category']]); $categoryId=(int)$category->fetchColumn();
        if(!$categoryId) throw new RuntimeException('Categoría no encontrada: '.$course['category']);
        $save=$db->prepare("INSERT INTO courses(category_id,level,title,slug,short_description,description,estimated_minutes,status,is_free,created_at,updated_at,published_at) VALUES(?,?,?,?,?,?,?,'published',1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE category_id=VALUES(category_id),level=VALUES(level),title=VALUES(title),short_description=VALUES(short_description),description=VALUES(description),estimated_minutes=VALUES(estimated_minutes),status='published',updated_at=CURRENT_TIMESTAMP");
        $save->execute([$categoryId,$course['level'],$course['title'],$course['slug'],$course['short'],$course['description'],$course['minutes']]);
        $id=(int)$db->query("SELECT id FROM courses WHERE slug=".$db->quote($course['slug']))->fetchColumn();
        if ($course['slug'] === 'propaga-tus-plantas') {
            $cover = 'front/images/propaga-tus-plantas-cover.png';
            $db->prepare('UPDATE courses SET cover_image_url=? WHERE id=?')->execute([$cover, $id]);
            self::reference($db,$id,null,'Imagen generada con IA: Propagación de plantas bajo luz matutina',$cover,'ai','Imagen generada con IA para la portada del curso. Prompt: Fotografía botánica realista de una mesa de trabajo limpia con esquejes de pothos, monstera y menta en frascos de vidrio transparentes, nudos y raíces jóvenes visibles, herramientas desinfectadas y etiquetas discretas, luz natural suave de mañana, tonos verdes cálidos, composición educativa sin personas, sin texto.',100);
        }
        if ($course['slug'] === 'composta-en-casa') {
            $cover = 'front/images/composta-en-casa-cover.png';
            $db->prepare('UPDATE courses SET cover_image_url=? WHERE id=?')->execute([$cover, $id]);
            self::reference($db,$id,null,'Imagen generada con IA: Compostera de jardín con capas orgánicas y albahaca fresca',$cover,'ai','Imagen generada con IA para la portada del curso. Prompt: Fotografía realista de una composta doméstica en contenedor de madera, capas visibles de hojas secas, restos vegetales y tierra oscura madura, pequeña maceta de albahaca junto al compost, luz natural de jardín, estilo limpio y educativo, sin personas, sin texto.',100);
        }
        if ($course['slug'] === 'jardin-para-polinizadores') {
            $cover = 'front/images/jardin-para-polinizadores-cover.png';
            $db->prepare('UPDATE courses SET cover_image_url=? WHERE id=?')->execute([$cover, $id]);
            self::reference($db,$id,null,'Imagen generada con IA: Jardín vibrante de cempasúchil y polinizadores',$cover,'ai','Imagen generada con IA para la portada del curso. Prompt: Fotografía de jardín mexicano para polinizadores con cempasúchil, cosmos, dalias y salvia en flor, mariposas y abejas observables sin ser el centro, diversidad de colores naturales, luz suave de mañana, composición acogedora y educativa, sin personas ni texto.',100);
        }
        if ($course['slug'] === 'suculentas-sin-exceso-de-riego') {
            $cover = 'front/images/suculentas-sin-exceso-de-riego-cover.png';
            $db->prepare('UPDATE courses SET cover_image_url=? WHERE id=?')->execute([$cover, $id]);
            self::reference($db,$id,null,'Imagen generada con IA: Colección de suculentas al sol',$cover,'ai','Imagen generada con IA para la portada del curso. Prompt: Fotografía editorial realista de colección de suculentas y cactus en macetas de barro con drenaje, echeverias, árbol de jade y sábila, sustrato mineral visible, luz solar lateral suave, fondo neutro verde, estilo educativo, sin personas ni texto.',100);
        }
        if ($course['slug'] === 'hogar-verde-seguro-para-mascotas') {
            $cover = 'front/images/hogar-verde-seguro-para-mascotas-cover.png';
            $db->prepare('UPDATE courses SET cover_image_url=? WHERE id=?')->execute([$cover, $id]);
            self::reference($db,$id,null,'Imagen generada con IA: Sala soleada con perro y gato',$cover,'ai','Imagen generada con IA para la portada del curso. Prompt: Fotografía realista de hogar luminoso con plantas de interior colocadas de forma segura en repisas altas, palma de salón y peperomias, perro y gato al fondo sin tocar las plantas, ambiente cálido, ordenado y responsable, sin texto ni personas.',100);
        }
        $db->prepare('DELETE FROM course_tags WHERE course_id=?')->execute([$id]);
        $tag=$db->prepare('INSERT INTO course_tags(course_id,tag_id,weight,is_required) SELECT ?,id,?,0 FROM tags WHERE code=?'); foreach($course['tags'] as $code=>$weight)$tag->execute([$id,$weight,$code]);
        $taxa=$db->prepare('INSERT INTO course_plant_taxa(course_id,plant_taxon_id,weight) SELECT ?,id,? FROM plant_taxa WHERE code=? ON DUPLICATE KEY UPDATE weight=VALUES(weight)'); foreach($course['plants'] as $code=>$weight)$taxa->execute([$id,$weight,$code]);
        $region=$db->prepare('INSERT INTO course_regions(course_id,region_id,weight) SELECT ?,id,70 FROM regions WHERE code=? ON DUPLICATE KEY UPDATE weight=VALUES(weight)'); foreach($course['regions'] as $code)$region->execute([$id,$code]);
        foreach($course['outcomes'] as $p=>$text)$db->prepare('INSERT INTO course_learning_outcomes(course_id,body,position) VALUES(?,?,?) ON DUPLICATE KEY UPDATE body=VALUES(body)')->execute([$id,$text,$p+1]);
        foreach($course['prerequisites'] as $p=>$text)$db->prepare('INSERT INTO course_prerequisites(course_id,body,position) VALUES(?,?,?) ON DUPLICATE KEY UPDATE body=VALUES(body)')->execute([$id,$text,$p+1]);
        foreach($course['modules'] as $position=>$module) {
            $find=$db->prepare('SELECT id FROM course_modules WHERE course_id=? AND position=?');$find->execute([$id,$position+1]);$moduleId=(int)$find->fetchColumn();
            if(!$moduleId){$db->prepare('INSERT INTO course_modules(course_id,title,description,position,estimated_minutes,is_required) VALUES(?,?,?,?,?,1)')->execute([$id,$module[0],$module[1],$position+1,30]);$moduleId=(int)$db->lastInsertId();}
            else $db->prepare('UPDATE course_modules SET title=?,description=?,estimated_minutes=30 WHERE id=?')->execute([$module[0],$module[1],$moduleId]);
            foreach([$module[0].': fundamentos',$module[0].': práctica guiada'] as $lessonPosition=>$title) {
                $lesson=$db->prepare('SELECT id FROM lessons WHERE module_id=? AND position=?');$lesson->execute([$moduleId,$lessonPosition+1]);$lessonId=(int)$lesson->fetchColumn();
                if(!$lessonId){$db->prepare('INSERT INTO lessons(module_id,title,description,position,estimated_minutes,is_required,is_preview) VALUES(?,?,?,?,15,1,?)')->execute([$moduleId,$title,$module[1],$lessonPosition+1,$position===0&&$lessonPosition===0]);$lessonId=(int)$db->lastInsertId();}
                $text="Contenido educativo generado con IA y revisado para guiar una práctica segura: {$module[1]} Observa las condiciones reales, registra lo que haces y consulta la fuente indicada antes de aplicar cambios importantes.";
                $block=$db->prepare("INSERT INTO lesson_blocks(lesson_id,type,title,body,content_data,position,is_required,low_bandwidth) VALUES(?,'text',?,?,NULL,1,1,0) ON DUPLICATE KEY UPDATE title=VALUES(title),body=VALUES(body)");$block->execute([$lessonId,$title,$text]);
                self::reference($db,$id,$lessonId,$course['source'][0],$course['source'][1],'external',$course['source'][2],$position+1);
            }
        }
        self::reference($db,$id,null,'OpenAI: contenido y estructura generados con IA','https://openai.com/','ai','Curso, módulos, prácticas y evaluación inicial elaborados con asistencia de IA; requiere revisión editorial y adaptación local.',99);
    }
    private static function reference(PDO $db,int $courseId,?int $lessonId,string $title,string $url,string $type,string $notes,int $position): void { $q=$db->prepare('SELECT id FROM content_references WHERE course_id=? AND lesson_id <=> ? AND title=?');$q->execute([$courseId,$lessonId,$title]);$id=(int)$q->fetchColumn(); if($id){$db->prepare('UPDATE content_references SET url=?,source_type=?,notes=?,position=? WHERE id=?')->execute([$url,$type,$notes,$position,$id]);return;} $db->prepare('INSERT INTO content_references(course_id,lesson_id,title,url,source_type,notes,position) VALUES(?,?,?,?,?,?,?)')->execute([$courseId,$lessonId,$title,$url,$type,$notes,$position]); }
    private static function courses(): array { return [
      ['slug'=>'propaga-tus-plantas','category'=>'propagation','level'=>'beginner','title'=>'Propaga tus plantas con confianza','short'=>'Esquejes, división y seguimiento sin adivinar.','description'=>'Curso práctico para elegir un método de propagación, trabajar con higiene y documentar resultados.','minutes'=>120,'tags'=>['interest-propagation'=>100,'topic-propagation'=>100,'topic-root-health'=>70],'plants'=>['species-epipremnum-aureum'=>100,'species-monstera-deliciosa'=>90,'species-mentha-spicata'=>85,'species-crassula-ovata'=>80],'regions'=>['urban-microclimate','temperate-subhumid'],'outcomes'=>['Elegir un método apropiado para una planta.','Preparar material limpio y seguro.','Registrar el progreso de un esqueje o división.'],'prerequisites'=>['Tijeras limpias y una planta apta para practicar.'],'modules'=>[['Elegir el método','Distingue esqueje, división y semilla según la estructura de la planta.'],['Preparar el material','Usa herramientas limpias, recipientes adecuados y etiquetas.'],['Enraizar y observar','Controla humedad, luz y señales de crecimiento sin intervenir de más.'],['Registrar y ajustar','Crea una bitácora para aprender de cada intento.']],'source'=>['UMN Extension: How and when to divide perennials','https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/dividing-perennials','División, establecimiento y observación responsable.']],
      ['slug'=>'composta-en-casa','category'=>'soil-ecology','level'=>'beginner','title'=>'Composta en casa: suelo vivo','short'=>'Convierte residuos vegetales en una enmienda útil y observable.','description'=>'Diseña una composta doméstica equilibrada, segura y adecuada para tu espacio.','minutes'=>120,'tags'=>['interest-composting'=>100,'topic-composting'=>100,'topic-soil-life'=>85],'plants'=>['species-ocimum-basilicum'=>60,'species-solanum-lycopersicum'=>70,'species-cucurbita-pepo'=>70,'species-phaseolus-vulgaris'=>65],'regions'=>['warm-humid','temperate-subhumid','urban-microclimate'],'outcomes'=>['Separar materiales apropiados para composta.','Equilibrar materiales húmedos y secos.','Reconocer cuándo una composta necesita ajuste.'],'prerequisites'=>['Un contenedor ventilado y residuos vegetales limpios.'],'modules'=>[['Qué sí compostar','Identifica materiales vegetales y evita contaminantes.'],['Armar capas equilibradas','Combina materiales secos y húmedos con aireación.'],['Observar temperatura y humedad','Interpreta olor, textura y actividad sin usar calendarios rígidos.'],['Usar la composta','Incorpora el material maduro en macetas o huerto.']],'source'=>['UMN Extension: Composting in home gardens','https://extension.umn.edu/planting-and-growing-guides/composting-home-gardens','Compostaje doméstico y manejo de materiales.']],
      ['slug'=>'jardin-para-polinizadores','category'=>'native-biodiversity','level'=>'intermediate','title'=>'Diseña un jardín para polinizadores','short'=>'Flores, diversidad y observación responsable de visitantes.','description'=>'Planifica un espacio con floración escalonada y especies adecuadas al contexto local.','minutes'=>120,'tags'=>['interest-pollinators'=>100,'interest-native'=>90,'topic-pollinators'=>100,'topic-native-plants'=>90],'plants'=>['species-tagetes-erecta'=>90,'species-dahlia-pinnata'=>90,'species-cosmos-bipinnatus'=>90,'species-salvia-officinalis'=>70],'regions'=>['temperate-subhumid','highland-urban','warm-dry'],'outcomes'=>['Diseñar una selección con floración escalonada.','Relacionar flores y visitantes sin manipular fauna.','Registrar observaciones útiles para mejorar el espacio.'],'prerequisites'=>['Un sitio de cultivo o plan de diseño.'],'modules'=>[['Observar antes de plantar','Reconoce luz, viento y recursos disponibles.'],['Elegir diversidad floral','Combina formas, colores y temporadas de floración.'],['Crear refugio y agua segura','Evita prácticas que dañen a polinizadores.'],['Medir resultados','Registra visitas y cambios del jardín.']],'source'=>['CONABIO POLINIZA','https://siagro.conabio.gob.mx/','Información mexicana sobre polinizadores y plantas.']],
      ['slug'=>'suculentas-sin-exceso-de-riego','category'=>'watering-nutrition','level'=>'beginner','title'=>'Suculentas sin exceso de riego','short'=>'Luz, drenaje y observación para cactus y suculentas.','description'=>'Aprende a ajustar el cuidado de plantas de reserva de agua según señales reales.','minutes'=>120,'tags'=>['interest-succulents-cacti'=>100,'topic-watering'=>100,'topic-drainage'=>100],'plants'=>['species-echeveria-elegans'=>100,'species-crassula-ovata'=>100,'species-aloe-vera'=>90,'species-opuntia-ficus-indica'=>80],'regions'=>['warm-dry','semiarid','northern-desert'],'outcomes'=>['Evaluar drenaje y recipiente.','Distinguir señales de exceso y falta de agua.','Ajustar exposición solar de forma gradual.'],'prerequisites'=>['Una suculenta o cactus y una maceta con drenaje.'],'modules'=>[['Entender la reserva de agua','Relaciona estructura, luz y consumo de agua.'],['Elegir recipiente y sustrato','Evita compactación y acumulación de humedad.'],['Regar con observación','Decide según sustrato y condiciones, no por calendario.'],['Resolver problemas comunes','Identifica daño por sol, pudrición y crecimiento débil.']],'source'=>['ASPCA: Are succulents safe to have around pets?','https://www.aspca.org/news/are-succulents-safe-have-around-pets','Seguridad de suculentas y precauciones con mascotas.']],
      ['slug'=>'hogar-verde-seguro-para-mascotas','category'=>'safety-wellbeing','level'=>'beginner','title'=>'Hogar verde seguro para mascotas','short'=>'Ubica, identifica y comunica riesgos de plantas en casa.','description'=>'Curso de prevención para convivir con plantas y mascotas sin sustituir atención veterinaria.','minutes'=>120,'tags'=>['safety-has-pets'=>100,'safety-pet-safe'=>100,'safety-toxic-plant'=>90],'plants'=>['species-epipremnum-aureum'=>100,'species-monstera-deliciosa'=>100,'species-dracaena-trifasciata'=>100,'species-chamaedorea-elegans'=>80],'regions'=>['urban-microclimate','temperate-subhumid','warm-humid'],'outcomes'=>['Identificar riesgos de ubicación y acceso.','Diferenciar prevención de atención médica.','Crear un plan doméstico de ubicación segura.'],'prerequisites'=>['Lista de plantas del hogar, si está disponible.'],'modules'=>[['Reconocer el riesgo','Consulta fuentes confiables antes de asumir seguridad.'],['Diseñar ubicaciones seguras','Reduce acceso sin depender solo del comportamiento de la mascota.'],['Actuar ante una posible ingestión','Prioriza contacto veterinario y evidencia de la planta.'],['Mantener un inventario','Actualiza nombres y ubicación de cada planta.']],'source'=>['ASPCA: Toxic and non-toxic plants','https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants','Base de consulta sobre toxicidad vegetal para animales.']],
